package org.apache.commons.cli2.commandline;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import java.util.Properties;
import java.util.Set;
import org.apache.commons.cli2.Argument;
import org.apache.commons.cli2.Option;
import org.apache.commons.cli2.WriteableCommandLine;
import org.apache.commons.cli2.option.PropertyOption;
import org.apache.commons.cli2.resource.ResourceConstants;
import org.apache.commons.cli2.resource.ResourceHelper;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class WriteableCommandLineImpl_getValues_TriageGen2Test {

    private WriteableCommandLineImpl commandLine;

    @Before
    public void setUp() {
        Option rootOption = new Option("root");
        commandLine = new WriteableCommandLineImpl(rootOption, Collections.emptyList());
    }

    @Test
    public void testGetValuesWithNonEmptyValues() {
        Option option = new Option("opt");
        List<String> values = Arrays.asList("val1", "val2");
        commandLine.setValues(option, values);

        List<String> result = commandLine.getValues(option, Collections.emptyList());
        assertEquals(values, result);
    }

    @Test
    public void testGetValuesWithEmptyValuesAndNonEmptyDefaults() {
        Option option = new Option("opt");
        List<String> defaultValues = Arrays.asList("default1", "default2");

        List<String> result = commandLine.getValues(option, defaultValues);
        assertEquals(defaultValues, result);
    }

    @Test
    public void testGetValuesWithNullValuesAndNonEmptyDefaults() {
        Option option = new Option("opt");
        List<String> defaultValues = Arrays.asList("default1", "default2");

        List<String> result = commandLine.getValues(option, defaultValues);
        assertEquals(defaultValues, result);
    }

    @Test
    public void testGetValuesWithEmptyAndNullValuesAndNonEmptyDefaultValues() {
        Option option = new Option("opt");
        commandLine.setDefaultValues(option, Arrays.asList("default1", "default2"));

        List<String> result = commandLine.getValues(option, Collections.emptyList());
        assertEquals(Arrays.asList("default1", "default2"), result);
    }

    @Test
    public void testGetValuesWithNullValuesAndNullDefaultsAndNonEmptyDefaultValues() {
        Option option = new Option("opt");
        commandLine.setDefaultValues(option, Arrays.asList("default1", "default2"));

        List<String> result = commandLine.getValues(option, null);
        assertEquals(Arrays.asList("default1", "default2"), result);
    }

    @Test
    public void testGetValuesWithNullValuesAndNullDefaultsAndEmptyDefaultValues() {
        Option option = new Option("opt");

        List<String> result = commandLine.getValues(option, null);
        assertEquals(Collections.EMPTY_LIST, result);
    }

    @Test
    public void testGetValuesWithNullOption() {
        List<String> result = commandLine.getValues(null, Arrays.asList("default1", "default2"));
        assertEquals(Collections.EMPTY_LIST, result);
    }

    @Test
    public void testGetValuesWithNullDefaults() {
        Option option = new Option("opt");

        List<String> result = commandLine.getValues(option, null);
        assertEquals(Collections.EMPTY_LIST, result);
    }
}
